const es = Object.fromEntries([...document.querySelectorAll('[data-i18n]')].map(el=>[el.dataset.i18n,el.innerHTML]));
const photoData = [
 ['assets/garden.jpg','El jardín y la pérgola','The garden and pergola'],
 ['assets/834723291_122118091935469192_6429898277367971862_n.jpg','Una mesa junto al mar','A table by the sea'],
 ['assets/832634803_122118092031469192_7765567669302365411_n.jpg','Pequeños detalles','The little details'],
 ['assets/832965046_122118091875469192_4663245563056024798_n.jpg','Momentos para celebrar','Moments to celebrate'],
 ['assets/831455647_122118091833469192_8500729452788754008_n.jpg','Una cálida bienvenida','A warm welcome'],
 ['assets/833276517_122118091827469192_3742007781647322213_n.jpg','La brisa del Pacífico','The Pacific breeze']
];
const packagePhotos=[['assets/830701723_122117649069469192_7355201890133626573_n.jpg','Paquete 1 · Publicación original en español','Package 1 · Original Spanish post'],['assets/publication.jpg','Paquete 2 · Publicación promocional; Facebook la etiqueta como contenido de IA','Package 2 · Promotional image; Facebook labels it as AI content']];
let lang='es',current=0,album=photoData;
const dialog=document.querySelector('#lightbox');
const icon='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M6 18 18 6M6 6h12v12"/></svg>';
function gallery(){document.querySelector('#gallery').replaceChildren();photoData.slice(0,5).forEach((p,i)=>{const button=document.createElement('button');button.type='button';button.setAttribute('aria-label',(lang==='es'?'Ampliar: ':'Enlarge: ')+p[lang==='es'?1:2]);const img=document.createElement('img');img.src=p[0];img.alt=p[lang==='es'?1:2];img.loading='lazy';img.width=i===0?960:443;img.height=i===0?720:590;const caption=document.createElement('span');caption.className='caption';const title=document.createElement('span');title.textContent=img.alt;caption.append(title);caption.insertAdjacentHTML('beforeend',icon);button.append(img,caption);button.addEventListener('click',()=>openGallery(photoData,i));document.querySelector('#gallery').append(button);});}
function renderPhoto(){const p=album[current];const image=document.querySelector('#large-image');image.src=p[0];image.alt=p[lang==='es'?1:2];document.querySelector('#image-caption').textContent=image.alt;document.querySelector('#image-count').textContent=`${current+1} / ${album.length}`;}
function openGallery(list,index){album=list;current=index;renderPhoto();dialog.showModal();document.body.classList.add('modal-open');}
function move(direction){current=(current+direction+album.length)%album.length;renderPhoto();}
document.querySelector('#close').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>document.body.classList.remove('modal-open'));
dialog.addEventListener('click',e=>{if(e.target===dialog){const b=dialog.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)dialog.close();}});
dialog.addEventListener('keydown',e=>{if(e.key==='ArrowRight'){e.preventDefault();move(1);}if(e.key==='ArrowLeft'){e.preventDefault();move(-1);}});
document.querySelector('#next').addEventListener('click',()=>move(1));document.querySelector('#prev').addEventListener('click',()=>move(-1));
document.querySelectorAll('[data-package]').forEach(b=>b.addEventListener('click',()=>openGallery(packagePhotos,Number(b.dataset.package)-1)));
const menu=document.querySelector('.menu'),nav=document.querySelector('#nav');
function closeMenu(){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');}
menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));});
nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu();});
function setLanguage(value){lang=value;document.documentElement.lang=lang;const dict=lang==='en'?en:es;document.querySelectorAll('[data-i18n]').forEach(el=>{el.innerHTML=dict[el.dataset.i18n]});document.querySelectorAll('[data-lang]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.lang===lang)));document.querySelector('[data-alt="gardenAlt"]').alt=lang==='es'?'Jardín de Rosarito Beach Garden con pérgola de madera, mesas y palmeras':'Rosarito Beach Garden with a wooden pergola, tables and palm trees';document.querySelector('[data-alt="seaAlt"]').alt=lang==='es'?'Mesa del jardín con vista al mar entre palmeras':'Garden table overlooking the ocean between palm trees';menu.setAttribute('aria-label',lang==='es'?'Abrir o cerrar menú':'Open or close menu');nav.setAttribute('aria-label',lang==='es'?'Principal':'Main');document.querySelector('#prev').setAttribute('aria-label',lang==='es'?'Foto anterior':'Previous photo');document.querySelector('#next').setAttribute('aria-label',lang==='es'?'Foto siguiente':'Next photo');document.querySelector('.brand').setAttribute('aria-label','Rosarito Beach Garden, '+(lang==='es'?'inicio':'home'));document.querySelector('.photo-caption a').setAttribute('aria-label',lang==='es'?'Descubrir el jardín':'Discover the garden');document.title=lang==='es'?'Rosarito Beach Garden — Celebra frente al mar':'Rosarito Beach Garden — Celebrate by the sea';document.querySelector('meta[name="description"]').content=lang==='es'?'Un jardín frente al mar en Rosarito para tus momentos especiales. Conoce el espacio, los paquetes para 60 personas y consulta tu evento.':'A seaside garden in Rosarito for your special moments. Explore the venue, packages for 60 guests and inquire about your event.';document.querySelector('#form-status').textContent='';gallery();document.dispatchEvent(new Event('rbg:language'));if(dialog.open)renderPhoto();try{localStorage.setItem('rbg-language',lang)}catch{}}
document.querySelectorAll('[data-lang]').forEach(b=>b.addEventListener('click',()=>setLanguage(b.dataset.lang)));
const dateInput=document.querySelector('#date');const today=new Date();dateInput.min=[today.getFullYear(),String(today.getMonth()+1).padStart(2,'0'),String(today.getDate()).padStart(2,'0')].join('-');
const form=document.querySelector('#inquiry');
function inquiry(){const data=new FormData(form);return lang==='es'?`Hola, Rosarito Beach Garden.\n\nSoy ${data.get('name')}. Me gustaría consultar disponibilidad y cotización para mi evento.\n\nCorreo de contacto: ${data.get('email') || 'No indicado'}\nEvento: ${data.get('event')}\nFecha tentativa: ${data.get('date')}\nInvitados: ${data.get('guests')}\n\n${data.get('message')}\n\nGracias.`:`Hello, Rosarito Beach Garden.\n\nMy name is ${data.get('name')}. I would like to ask about availability and pricing for my event.\n\nContact email: ${data.get('email') || 'Not provided'}\nEvent: ${data.get('event')}\nPreferred date: ${data.get('date')}\nGuests: ${data.get('guests')}\n\n${data.get('message')}\n\nThank you.`;}
form.addEventListener('submit',e=>{e.preventDefault();const subject=lang==='es'?'Consulta de evento — Rosarito Beach Garden':'Event inquiry — Rosarito Beach Garden';window.location.href=`mailto:rosaritobeachgarden@gmail.com?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(inquiry())}`;document.querySelector('#form-status').textContent=lang==='es'?'Consulta preparada. Si no se abrió tu correo, usa “Copiar consulta” y envíala al correo indicado.':'Inquiry prepared. If your email app did not open, use “Copy inquiry” and send it to the listed email address.';});
document.querySelector('#copy').addEventListener('click',async()=>{if(!form.reportValidity())return;try{await navigator.clipboard.writeText(inquiry());document.querySelector('#form-status').textContent=lang==='es'?'Consulta copiada. Pégala en tu correo o en un mensaje de Facebook.':'Inquiry copied. Paste it into your email or a Facebook message.';}catch{document.querySelector('#form-status').textContent=lang==='es'?'No se pudo copiar. Usa el botón de correo o escribe directamente al correo indicado.':'Could not copy. Use the email button or write directly to the listed address.';}});
let preferred='es';try{if(localStorage.getItem('rbg-language')==='en')preferred='en'}catch{}setLanguage(preferred);
